import { MODULE_TITLE } from "../../constants";
import { notifyError } from "../../notifications/notify-user";

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * Surface an asynchronous Paper Doll integration failure in both Foundry's UI
 * and the browser console, so a rejected document update cannot be mistaken
 * for a successful equipment change.
 */
export function reportPaperDollError(context: string, error: unknown): void {
  const message = `${MODULE_TITLE}: ${context}. ${getErrorMessage(error)}`;

  notifyError(message, error);
}

/**
 * Foundry hooks do not await every callback. Use this only at those hook
 * boundaries, and always make a rejected task visible to the user.
 */
export function runPaperDollTask(task: Promise<unknown>, context: string): void {
  void task.catch((error: unknown) => reportPaperDollError(context, error));
}
