import {
  deriveArgonWeaponSetsFromPaperDoll,
  getPaperDollMainHandSlots,
  haveSameArgonWeaponSets,
  selectPaperDollQuickItemUuids,
} from "../../../functions/integrations/paper-doll-argon/bridge";
import { isPaperDollSlotState } from "../../../functions/patches/paper-doll/is-paper-doll-slot-state";
import type {
  ArgonWeaponSetFlag,
  ArgonWeaponSetFlags,
  PaperDollArgonSyncResult,
} from "../../../types/integrations/paper-doll-argon/Bridge";
import type { PaperDollSlotState } from "../../../types/patches/paper-doll/Equipment";
import { ARGON_MODULE_ID } from "../enhancedcombathud/constants";
import { refreshMountedArgonHud } from "../enhancedcombathud/refresh";
import { PAPER_DOLL_MODULE_ID } from "../fvtt-paper-doll-ui/register-integration";
import { getActorMainHand } from "../../patches/paper-doll/wfrp-equipment";
import { isRecord, isWfrpActor, type WfrpActor } from "../../patches/paper-doll/wfrp-runtime-types";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";

const ACTIVE_WEAPON_SET_FLAG = "activeWeaponSet";
const PAPER_DOLL_SLOT_FLAG = "slots";
const WEAPON_SETS_FLAG = "weaponSets";

function getPaperDollSlotState(actor: WfrpActor): PaperDollSlotState {
  const value = actor.getFlag(PAPER_DOLL_MODULE_ID, PAPER_DOLL_SLOT_FLAG);

  if (value === undefined) {
    return {};
  }

  if (!isPaperDollSlotState(value)) {
    throw new Error(`Paper Doll slots for ${actor.uuid} have an invalid shape.`);
  }

  return value;
}

function getActiveWeaponSetId(actor: WfrpActor): string {
  const value = actor.getFlag(ARGON_MODULE_ID, ACTIVE_WEAPON_SET_FLAG);

  if (value === undefined) {
    return "1";
  }

  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`Argon's active weapon set for ${actor.uuid} is invalid.`);
  }

  return value;
}

function getWeaponSetSlot(value: unknown, context: string): string | null | undefined {
  if (value === undefined || value === null || (typeof value === "string" && value.length > 0)) {
    return value as string | null | undefined;
  }

  throw new Error(`${context} must contain an item UUID, null, or be absent.`);
}

function getArgonWeaponSets(actor: WfrpActor): ArgonWeaponSetFlags {
  const value = actor.getFlag(ARGON_MODULE_ID, WEAPON_SETS_FLAG);

  if (value === undefined) {
    return {};
  }

  if (!isRecord(value)) {
    throw new Error(`Argon weapon sets for ${actor.uuid} have an invalid shape.`);
  }

  return Object.fromEntries(
    Object.entries(value).map(([setId, slots]) => {
      if (!setId || !isRecord(slots)) {
        throw new Error(`Argon weapon set ${setId || "<empty>"} has an invalid shape.`);
      }

      const parsed: ArgonWeaponSetFlag = {
        primary: getWeaponSetSlot(slots["primary"], `Argon weapon set ${setId} primary slot`),
        secondary: getWeaponSetSlot(slots["secondary"], `Argon weapon set ${setId} secondary slot`),
      };
      return [setId, parsed];
    }),
  );
}

async function synchronizeActor(
  actor: WfrpActor,
  slots: PaperDollSlotState,
): Promise<PaperDollArgonSyncResult> {
  const current = getArgonWeaponSets(actor);
  const next = deriveArgonWeaponSetsFromPaperDoll({
    activeSetId: getActiveWeaponSetId(actor),
    mainHand: getActorMainHand(actor),
    mainSlots: getPaperDollMainHandSlots(slots),
    weaponSets: current,
  });
  const changed = !haveSameArgonWeaponSets(current, next);

  if (changed) {
    await actor.setFlag(ARGON_MODULE_ID, WEAPON_SETS_FLAG, next);
  }

  await refreshMountedArgonHud();
  return changed ? "synchronized" : "unchanged";
}

export function getPaperDollQuickItems(actorValue: unknown) {
  if (!isWfrpActor(actorValue)) {
    throw new Error("Paper Doll quick items require a WFRP actor document.");
  }

  const itemByUuid = new Map(Array.from(actorValue.items, (item) => [item.uuid, item]));
  return selectPaperDollQuickItemUuids(getPaperDollSlotState(actorValue)).map((uuid) => {
    const item = itemByUuid.get(uuid);

    if (!item) {
      throw new Error(`Paper Doll quick slot item ${uuid} is not owned by ${actorValue.uuid}.`);
    }

    if (item.type === "weapon" || item.type === "armour") {
      throw new Error(`Paper Doll quick slot ${uuid} contains ${item.type} equipment.`);
    }

    return item;
  });
}

export function getUpdatedPaperDollSlots(changes: unknown): PaperDollSlotState | null {
  if (!isRecord(changes) || !("flags" in changes)) {
    return null;
  }

  const flags = changes["flags"];
  if (!isRecord(flags) || !(PAPER_DOLL_MODULE_ID in flags)) {
    return null;
  }

  const paperDollFlags = flags[PAPER_DOLL_MODULE_ID];
  if (!isRecord(paperDollFlags) || !(PAPER_DOLL_SLOT_FLAG in paperDollFlags)) {
    return null;
  }

  const slots = paperDollFlags[PAPER_DOLL_SLOT_FLAG];
  if (!isPaperDollSlotState(slots)) {
    throw new Error("The updated Paper Doll slots have an invalid shape.");
  }

  return slots;
}

export async function syncPaperDollArgonActor(
  actorValue: unknown,
): Promise<PaperDollArgonSyncResult> {
  if (!isWfrpActor(actorValue)) {
    throw new Error("Paper Doll–Argon synchronization requires a WFRP actor document.");
  }

  if (
    !isOptionalFeatureEnabled("paperDoll") ||
    !isOptionalFeatureEnabled("argonCombatHud") ||
    !isOptionalFeatureEnabled("paperDollArgonBridge")
  ) {
    return "unavailable";
  }

  if (actorValue.getFlag(PAPER_DOLL_MODULE_ID, PAPER_DOLL_SLOT_FLAG) === undefined) {
    await refreshMountedArgonHud();
    return "unchanged";
  }

  return synchronizeActor(actorValue, getPaperDollSlotState(actorValue));
}
