import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { isWfrpActor } from "../../patches/paper-doll/wfrp-runtime-types";
import { ARGON_MODULE_ID } from "../enhancedcombathud/constants";
import { PAPER_DOLL_MODULE_ID } from "../fvtt-paper-doll-ui/register-integration";
import { isModuleActive } from "../is-module-active";
import { getUpdatedPaperDollSlots, syncPaperDollArgonActor } from "./bridge-runtime";
import { createPaperDollArgonPanels } from "./panels";
import { runPaperDollArgonBridgeTask } from "./report-bridge-error";

export function isPaperDollArgonBridgeEnabled(): boolean {
  return (
    isOptionalFeatureEnabled("paperDoll") &&
    isOptionalFeatureEnabled("argonCombatHud") &&
    isOptionalFeatureEnabled("paperDollArgonBridge")
  );
}

function handlePaperDollActorUpdate(actorValue: unknown, changes: unknown): void {
  if (!isPaperDollArgonBridgeEnabled() || !isWfrpActor(actorValue)) {
    return;
  }

  if (!getUpdatedPaperDollSlots(changes)) {
    return;
  }

  runPaperDollArgonBridgeTask(
    // Foundry supplies only the differential data to updateActor hooks. Read
    // the complete persisted flag from the updated actor before deriving the
    // active Argon weapon set.
    syncPaperDollArgonActor(actorValue),
    `could not synchronize Paper Doll slots with Argon for ${actorValue.uuid}`,
  );
}

export function registerPaperDollArgonBridge(): void {
  if (!isModuleActive(PAPER_DOLL_MODULE_ID)) {
    return;
  }

  if (!isModuleActive(ARGON_MODULE_ID)) {
    return;
  }

  if (!isPaperDollArgonBridgeEnabled()) {
    return;
  }

  Hooks.on("argonInit", (CoreHUD) => {
    const { PaperDollQuickItemsPanel } = createPaperDollArgonPanels(CoreHUD);
    CoreHUD.defineMainPanels([PaperDollQuickItemsPanel]);
  });
  Hooks.on("updateActor", handlePaperDollActorUpdate);
}
