import {
  mergeWfrpSplatterBloodColors,
  WFRP_SPLATTER_SPECIES_PATH,
} from "../../../functions/integrations/splatter/configuration";
import type { SplatterConfigurationResult } from "../../../types/integrations/splatter/Configuration";
import { isModuleActive } from "../is-module-active";
import {
  SPLATTER_AUTOMATIC_BLOOD_COLORS_SETTING,
  SPLATTER_BLOOD_COLORS_SETTING,
  SPLATTER_MODULE_ID,
  SPLATTER_SPECIES_PATH_SETTING,
} from "./constants";

const REQUIRED_SPLATTER_SETTINGS = [
  SPLATTER_BLOOD_COLORS_SETTING,
  SPLATTER_SPECIES_PATH_SETTING,
  SPLATTER_AUTOMATIC_BLOOD_COLORS_SETTING,
] as const;

function getConfiguredWfrpSpecies(): Readonly<Record<string, string>> {
  return game?.wfrp4e?.config.species ?? {};
}

function assertSplatterSettingsRegistered(): void {
  const registeredSettings = game?.settings.settings;

  if (!registeredSettings) {
    return;
  }

  for (const setting of REQUIRED_SPLATTER_SETTINGS) {
    if (!registeredSettings.has(`${SPLATTER_MODULE_ID}.${setting}`)) {
      throw new Error(`Splatter setting ${setting} is unavailable.`);
    }
  }
}

export async function configureSplatter(): Promise<SplatterConfigurationResult> {
  if (!game) {
    throw new Error("Foundry game is unavailable while configuring Splatter.");
  }

  if (!game.ready) {
    throw new Error("Foundry must finish loading before Splatter can be configured.");
  }

  if (!isModuleActive(SPLATTER_MODULE_ID)) {
    throw new Error("Splatter must be active before it can be configured.");
  }

  if (!game.user?.isGM) {
    throw new Error("Only a gamemaster can change Splatter's world settings.");
  }

  assertSplatterSettingsRegistered();

  const bloodColors = mergeWfrpSplatterBloodColors(
    game.settings.get(SPLATTER_MODULE_ID, SPLATTER_BLOOD_COLORS_SETTING),
    getConfiguredWfrpSpecies(),
  );

  await game.settings.set(SPLATTER_MODULE_ID, SPLATTER_BLOOD_COLORS_SETTING, bloodColors);
  await game.settings.set(
    SPLATTER_MODULE_ID,
    SPLATTER_SPECIES_PATH_SETTING,
    WFRP_SPLATTER_SPECIES_PATH,
  );
  await game.settings.set(SPLATTER_MODULE_ID, SPLATTER_AUTOMATIC_BLOOD_COLORS_SETTING, true);

  return {
    automaticBloodColors: true,
    bloodColorCount: Object.keys(bloodColors).length,
    speciesPath: WFRP_SPLATTER_SPECIES_PATH,
  };
}
