export type SplatterBloodColors = Record<string, string>;

export const WFRP_SPLATTER_SPECIES_PATH = "details.species.value";

const REGULAR_RED = "#a51414d8";
const DWARF_DEEP_RED = "#7e1717dc";
const HALFLING_BRIGHT_RED = "#b31f18d8";
const HIGH_ELF_CRIMSON = "#b01832d8";
const WOOD_ELF_WINE_RED = "#861a24d8";
const OGRE_DARK_RED = "#541e1ed8";
