import type {
  ArmourEquipmentSnapshot,
  EquipmentSnapshot,
} from "../../../types/patches/paper-doll/Equipment";

function isArmourAllowedInSlot(item: ArmourEquipmentSnapshot, slotId: string): boolean {
  switch (slotId) {
    case "HEAD":
      return item.armourPoints.head > 0;
    case "BODY":
      return item.armourPoints.body > 0;
    case "GLOVES":
      return item.armourPoints.lArm > 0 || item.armourPoints.rArm > 0;
    case "BOOTS":
      return item.armourPoints.lLeg > 0 || item.armourPoints.rLeg > 0;
    default:
      return false;
  }
}

/** Keep physical WFRP slots type-safe while allowing other Paper Doll presentation slots. */
export function isPaperDollItemAllowedInSlot(
  itemType: string,
  equipment: EquipmentSnapshot | null,
  slotId: string,
): boolean {
  if (slotId === "MAIN_LEFT" || slotId === "MAIN_RIGHT") {
    return equipment?.type === "weapon";
  }

  if (slotId === "HEAD" || slotId === "BODY" || slotId === "GLOVES" || slotId === "BOOTS") {
    return equipment?.type === "armour" && isArmourAllowedInSlot(equipment, slotId);
  }

  return itemType !== "weapon" && itemType !== "armour";
}
