import { MODULE_TITLE } from "../../constants";
import { notifyError } from "../../notifications/notify-user";

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export function reportPaperDollArgonBridgeError(context: string, error: unknown): void {
  const message = `${MODULE_TITLE}: ${context}. ${getErrorMessage(error)}`;

  notifyError(message, error);
}

export function runPaperDollArgonBridgeTask(task: Promise<unknown>, context: string): void {
  void task.catch((error: unknown) => reportPaperDollArgonBridgeError(context, error));
}
