import type { OptionalFeatureId } from "../../types/module/OptionalFeature";
import { MODULE_ID } from "../constants";
import { isOptionalFeatureAvailable, OPTIONAL_FEATURES } from "./optional-features";

export function isOptionalFeatureEnabled(featureId: OptionalFeatureId): boolean {
  const feature = OPTIONAL_FEATURES[featureId];

  return (
    isOptionalFeatureAvailable(featureId) &&
    game?.settings.get(MODULE_ID, feature.settingKey) !== false
  );
}
