import { isModuleActive } from "../is-module-active";
import { MODULE_ID } from "../../constants";
import { SPLATTER_MODULE_ID } from "./constants";
import { SplatterConfigurationMenu } from "./configuration-menu";

const LOCALIZATION_ROOT = `${MODULE_ID}.Splatter.Configuration`;

export function registerSplatterIntegration(): void {
  if (!isModuleActive(SPLATTER_MODULE_ID)) {
    return;
  }

  if (!game) {
    throw new Error(`${MODULE_ID} | Foundry game is unavailable during Splatter registration.`);
  }

  game.settings.registerMenu(MODULE_ID, "configureSplatter", {
    hint: `${LOCALIZATION_ROOT}.Hint`,
    icon: "fa-solid fa-droplet",
    label: `${LOCALIZATION_ROOT}.Button`,
    name: `${LOCALIZATION_ROOT}.Name`,
    restricted: true,
    type: SplatterConfigurationMenu,
  });
}
