/** Refresh Argon when its HUD is mounted, while exposing a changed mounted-HUD API. */
export async function refreshMountedArgonHud(): Promise<void> {
  const argon = ui?.ARGON;

  if (!argon) {
    return;
  }

  if (typeof argon.refresh !== "function") {
    throw new Error("Argon's mounted HUD does not expose its required refresh API.");
  }

  await argon.refresh.call(argon);
}
