import type {
  EquipmentSnapshot,
  PaperDollSlotAddress,
  WfrpHand,
} from "../../../types/patches/paper-doll/Equipment";

export type PaperDollEquipmentUpdate = Record<string, boolean>;

function getPhysicalHand(slot: PaperDollSlotAddress): WfrpHand | null {
  if (slot.slotId === "MAIN_LEFT") {
    return "l";
  }

  if (slot.slotId === "MAIN_RIGHT") {
    return "r";
  }

  return null;
}

export function derivePaperDollEquipUpdate(
  snapshot: EquipmentSnapshot | null,
  equipped: boolean | null,
  slot: PaperDollSlotAddress,
  mainHand: WfrpHand | null,
): PaperDollEquipmentUpdate {
  if (equipped === null) {
    return {};
  }

  const update: PaperDollEquipmentUpdate = {};

  if (!equipped) {
    update["system.equipped.value"] = true;
  }

  if (snapshot?.type !== "weapon") {
    return update;
  }

  if (!mainHand) {
    throw new Error(`Weapon ${snapshot.uuid} requires the actor's main hand.`);
  }

  const physicalHand = getPhysicalHand(slot);
  const desiredOffhand = snapshot.twoHanded
    ? false
    : physicalHand
      ? physicalHand !== mainHand
      : undefined;

  if (desiredOffhand !== undefined && snapshot.offhand !== desiredOffhand) {
    update["system.offhand.value"] = desiredOffhand;
  }

  return update;
}

export function derivePaperDollUnequipUpdate(equipped: boolean | null): PaperDollEquipmentUpdate {
  return equipped === true ? { "system.equipped.value": false } : {};
}
