import type { OptionalFeatureId } from "../../types/module/OptionalFeature";
import { MODULE_ID } from "../constants";
import { refreshMountedArgonHud } from "../integrations/enhancedcombathud/refresh";
import { isOptionalFeatureAvailable, OPTIONAL_FEATURES } from "./optional-features";

export const ARGON_COMBAT_ITEM_PATTERNS_SETTING = "argonCombatItemPatterns";
export const DEFAULT_ARGON_COMBAT_ITEM_PATTERNS = "*Draught*, *Potion*";

type FoundrySettings = NonNullable<typeof game>["settings"];

function registerFeatureToggle(settings: FoundrySettings, featureId: OptionalFeatureId): void {
  const feature = OPTIONAL_FEATURES[featureId];

  if (!isOptionalFeatureAvailable(featureId)) {
    return;
  }

  settings.register(MODULE_ID, feature.settingKey, {
    config: true,
    default: true,
    hint: `${MODULE_ID}.Settings.Features.${featureId}.Hint`,
    name: `${MODULE_ID}.Settings.Features.${featureId}.Name`,
    requiresReload: true,
    scope: "world",
    type: Boolean,
  });
}

function registerArgonSettings(settings: FoundrySettings): void {
  if (!isOptionalFeatureAvailable("argonCombatHud")) {
    return;
  }

  settings.register(MODULE_ID, ARGON_COMBAT_ITEM_PATTERNS_SETTING, {
    config: true,
    default: DEFAULT_ARGON_COMBAT_ITEM_PATTERNS,
    hint: `${MODULE_ID}.Settings.ArgonCombatItemPatterns.Hint`,
    name: `${MODULE_ID}.Settings.ArgonCombatItemPatterns.Name`,
    onChange: refreshMountedArgonHud,
    scope: "world",
    type: String,
  });
}

export function registerModuleSettings(): void {
  if (!game) {
    throw new Error(`${MODULE_ID} | Foundry game is unavailable during settings registration.`);
  }

  registerFeatureToggle(game.settings, "argonCombatHud");
  registerFeatureToggle(game.settings, "paperDoll");
  registerFeatureToggle(game.settings, "paperDollArgonBridge");
  registerArgonSettings(game.settings);
}
